<?php
declare(strict_types=1);
namespace StageArtPlugIn\Presentation\Admin;
final class SurveyQrAdmin{
 public function register():void{add_submenu_page(null,'アンケートQRコード','アンケートQRコード','manage_options','stageart-survey-qr',[$this,'render']);}
 public function render():void{if(!current_user_can('manage_options'))wp_die('権限がありません。');$pid=(int)($_GET['production_id']??0);$p=$pid?get_post($pid):null;if(!$p||$p->post_type!=='stageart_production')wp_die('公演が指定されていません。');$url=home_url('/production/'.($p->post_name?:$pid).'/questionnaire/');echo '<div class="wrap"><h1>アンケートQRコード</h1><p><strong>公演：</strong>'.esc_html($p->post_title).'</p><p>下のQRコードを公演会場などで印刷してご利用ください。</p><div id="stageart-survey-qr" style="width:320px;height:320px;margin:24px 0"></div><p><code>'.esc_html($url).'</code></p><p><button type="button" class="button button-primary" onclick="window.print()">QRコードを印刷</button></p></div><style>@media print{#wpadminbar,#adminmenumain,#wpfooter,#wpcontent>.wrap>h1,#wpcontent>.wrap>p{display:none!important}#wpcontent{margin-left:0!important}.wrap{margin:0!important}.wrap #stageart-survey-qr{margin:40px auto!important}.wrap:before{content:"'.esc_js($p->post_title).'\A アンケート";white-space:pre;text-align:center;display:block;font-size:24px;font-weight:700;margin:30px}</style><script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script>document.addEventListener("DOMContentLoaded",function(){new QRCode(document.getElementById("stageart-survey-qr"),{text:'.wp_json_encode($url).',width:320,height:320});});</script>';} }
